      "orig": "Ἀδελφοί, ἐὰν καὶ προλημφθῇ ἄνθρωπος ἔν τινι παραπτώματι, \nὑμεῖς οἱ πνευματικοὶ καταρτίζετε τὸν τοιοῦτον \nἐν πνεύματι πραΰτητος, \nσκοπῶν σεαυτόν μὴ καὶ σὺ πειρασθῇς.",
      "strong": "G80 (弟兄們), G1437 (若), G444 (有人), G1722 (偶然被)",
      "id": 692,
      "catIndex": 26
